/**
 * ARL - Adaptive Reinforcement Learning
 * Genuine 3D Trained-Policy Flight Replay & Simulation Engine (Three.js)
 *
 * Visualizes the actual recorded trajectory, quaternion attitudes, spherical
 * obstacles, and 16-ray LiDAR rangefinder readings generated by a genuine
 * trained PPO/SAC neural policy.
 */

(function () {
  'use strict';

  // Constants
  const ARENA_X = 30.0;
  const ARENA_Y = 30.0;
  const ARENA_Z = 15.0;
  const NUM_RAYS = 16;

  // 16 spherical unit vectors for simulated LiDAR rays
  const LIDAR_RAYS = [];
  for (let i = 0; i < NUM_RAYS; i++) {
    const phi = Math.acos(1 - 2 * (i + 0.5) / NUM_RAYS);
    const theta = Math.PI * (1 + Math.sqrt(5)) * (i + 0.5);
    LIDAR_RAYS.push(new THREE.Vector3(
      Math.sin(phi) * Math.cos(theta),
      Math.sin(phi) * Math.sin(theta),
      Math.cos(phi)
    ).normalize());
  }

  // Engine State
  let flightData = null;
  let trajectory = [];
  let numSteps = 0;
  let dt = 0.05;
  let is6DOF = true;

  let isRunning = false;
  let playhead = 0.0;
  let playbackSpeed = 1.0;
  let cameraFollow = false;

  let scene, camera, renderer, container;
  let droneMesh, propMeshes = [];
  let targetMesh, obstacleGroup;
  let trajectoryLine;
  let lidarSegments;

  // Camera Orbit Drag State
  let isDragging = false;
  let prevMousePos = { x: 0, y: 0 };
  let spherical = { radius: 50, theta: 0.85, phi: 1.15 };

  function init() {
    container = document.getElementById('hero-sim-canvas-wrap');
    if (!container || typeof THREE === 'undefined') return;

    // Load actual recorded flight replay artifact
    fetch('data/flight.json')
      .then(response => {
        if (!response.ok) throw new Error('HTTP ' + response.status);
        return response.json();
      })
      .then(data => {
        setupSimulation(data);
      })
      .catch(err => {
        console.warn('Could not load data/flight.json; checking alternative paths', err);
        // Fallback fetch path for Streamlit or root environments
        fetch('docs/data/flight.json')
          .then(r => r.json())
          .then(data => setupSimulation(data))
          .catch(e => {
            console.error('Failed to load recorded flight rollout:', e);
            showError('Flight replay data unavailable.');
          });
      });
  }

  function showError(msg) {
    const statusText = document.getElementById('sim-status-text');
    if (statusText) statusText.textContent = 'DATA ERROR';
    const note = document.querySelector('.sim-footer-note');
    if (note) note.innerHTML = '<span style="color:#ef4444;">⚠️ ' + msg + '</span>';
  }

  function setupSimulation(data) {
    flightData = data;
    trajectory = data.trajectory || [];
    numSteps = Math.max(0, trajectory.length - 1);
    dt = data.dt || 0.05;
    is6DOF = (data.dynamics_mode === '6-DOF') || (trajectory[0] && trajectory[0].quaternion !== null);

    const width = container.clientWidth || 600;
    const height = container.clientHeight || 380;

    // Three.js Scene Setup (Z-Up convention)
    scene = new THREE.Scene();
    scene.background = new THREE.Color(0x060a14);
    scene.fog = new THREE.FogExp2(0x060a14, 0.012);

    camera = new THREE.PerspectiveCamera(45, width / height, 0.5, 200);
    camera.up.set(0, 0, 1);
    updateCameraPosition();

    renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;

    // Clear any previous canvas
    const oldCanvas = container.querySelector('canvas');
    if (oldCanvas) oldCanvas.remove();
    container.appendChild(renderer.domElement);

    // Lights
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.65);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0x00f2fe, 0.85);
    dirLight.position.set(ARENA_X / 2, ARENA_Y / 2, 35);
    scene.add(dirLight);

    const blueLight = new THREE.PointLight(0x38bdf8, 1.0, 60);
    blueLight.position.set(5, 5, 12);
    scene.add(blueLight);

    buildArena();
    buildObstacles();
    buildTarget();
    buildDrone();
    buildLidar();
    buildTrajectoryLine();
    bindControls();

    // Set initial frame at t=0
    applyState(0.0);

    // Update footer badge
    const note = document.querySelector('.sim-footer-note');
    if (note) {
      const algo = flightData.algorithm || 'PPO';
      const env = flightData.environment || 'Drone6DOFEnv';
      const steps = trajectory.length;
      note.innerHTML = `● <b>RECORDED TRAINED-POLICY ROLLOUT:</b> Algorithm: <b>${algo}</b> | Env: <b>${env}</b> | Seed: <b>${flightData.seed ?? 42}</b> | <b>${steps}</b> Steps recorded with deterministic inference.`;
    }

    // Start requestAnimationFrame render loop
    requestAnimationFrame(render);
  }

  function buildArena() {
    const grid = new THREE.GridHelper(ARENA_X, 30, 0x00f2fe, 0x1e293b);
    grid.rotation.x = Math.PI / 2;
    grid.position.set(ARENA_X / 2, ARENA_Y / 2, 0);
    scene.add(grid);

    const boxGeom = new THREE.BoxGeometry(ARENA_X, ARENA_Y, ARENA_Z);
    const boxEdges = new THREE.EdgesGeometry(boxGeom);
    const boxMat = new THREE.LineBasicMaterial({ color: 0x1e293b, transparent: true, opacity: 0.6 });
    const box = new THREE.LineSegments(boxEdges, boxMat);
    box.position.set(ARENA_X / 2, ARENA_Y / 2, ARENA_Z / 2);
    scene.add(box);
  }

  function buildObstacles() {
    obstacleGroup = new THREE.Group();
    const obstacles = flightData.obstacles || [];
    obstacles.forEach(obs => {
      const pos = obs.position || [0, 0, 0];
      const r = obs.radius || 2.0;

      const geom = new THREE.SphereGeometry(r, 24, 24);
      const mat = new THREE.MeshStandardMaterial({
        color: 0xef4444,
        roughness: 0.4,
        metalness: 0.2,
        transparent: true,
        opacity: 0.8
      });
      const mesh = new THREE.Mesh(geom, mat);
      mesh.position.set(pos[0], pos[1], pos[2]);

      const wire = new THREE.LineSegments(
        new THREE.WireframeGeometry(geom),
        new THREE.LineBasicMaterial({ color: 0xff7b7b, transparent: true, opacity: 0.25 })
      );
      mesh.add(wire);
      obstacleGroup.add(mesh);
    });
    scene.add(obstacleGroup);
  }

  function buildTarget() {
    const targetPos = (flightData.target && flightData.target.position) ? flightData.target.position : [25, 25, 10];
    const group = new THREE.Group();
    const geom = new THREE.OctahedronGeometry(1.2, 0);
    const mat = new THREE.MeshStandardMaterial({
      color: 0x10b981,
      emissive: 0x10b981,
      emissiveIntensity: 0.7
    });
    targetMesh = new THREE.Mesh(geom, mat);
    group.add(targetMesh);

    const beaconGeom = new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(0, 0, 0),
      new THREE.Vector3(0, 0, -targetPos[2])
    ]);
    const beaconMat = new THREE.LineDashedMaterial({ color: 0x10b981, dashSize: 0.5, gapSize: 0.5, transparent: true, opacity: 0.5 });
    const beacon = new THREE.Line(beaconGeom, beaconMat);
    beacon.computeLineDistances();
    group.add(beacon);

    group.position.set(targetPos[0], targetPos[1], targetPos[2]);
    scene.add(group);
  }

  function buildDrone() {
    droneMesh = new THREE.Group();

    // Fuselage
    const bodyGeom = new THREE.CylinderGeometry(0.35, 0.42, 0.18, 16);
    bodyGeom.rotateX(Math.PI / 2);
    const bodyMat = new THREE.MeshStandardMaterial({ color: 0x0f172a, metalness: 0.8, roughness: 0.25 });
    droneMesh.add(new THREE.Mesh(bodyGeom, bodyMat));

    // Arms
    const armGeom = new THREE.BoxGeometry(1.4, 0.07, 0.06);
    const armMat = new THREE.MeshStandardMaterial({ color: 0x334155 });
    const a1 = new THREE.Mesh(armGeom, armMat);
    a1.rotation.z = Math.PI / 4;
    const a2 = new THREE.Mesh(armGeom, armMat);
    a2.rotation.z = -Math.PI / 4;
    droneMesh.add(a1);
    droneMesh.add(a2);

    // 4 Rotors & spinning propellers
    const armOffset = 0.50;
    const motorPos = [
      { x: armOffset, y: armOffset, isFront: true },
      { x: -armOffset, y: armOffset, isFront: true },
      { x: armOffset, y: -armOffset, isFront: false },
      { x: -armOffset, y: -armOffset, isFront: false }
    ];

    propMeshes = [];
    motorPos.forEach(m => {
      const motorGeom = new THREE.CylinderGeometry(0.09, 0.09, 0.12, 12);
      motorGeom.rotateX(Math.PI / 2);
      const motor = new THREE.Mesh(motorGeom, new THREE.MeshStandardMaterial({ color: 0x1e293b, metalness: 0.7 }));
      motor.position.set(m.x, m.y, 0.06);
      droneMesh.add(motor);

      const propGeom = new THREE.BoxGeometry(0.55, 0.05, 0.015);
      const propMat = new THREE.MeshStandardMaterial({
        color: m.isFront ? 0x00f2fe : 0xf59e0b,
        emissive: m.isFront ? 0x00f2fe : 0xf59e0b,
        emissiveIntensity: 0.35,
        transparent: true,
        opacity: 0.85
      });
      const prop = new THREE.Mesh(propGeom, propMat);
      prop.position.set(m.x, m.y, 0.13);
      droneMesh.add(prop);
      propMeshes.push(prop);
    });

    // Front Nose Indicator (Blue Cone)
    const noseGeom = new THREE.ConeGeometry(0.12, 0.28, 12);
    noseGeom.rotateZ(-Math.PI / 2);
    const nose = new THREE.Mesh(noseGeom, new THREE.MeshBasicMaterial({ color: 0x00f2fe }));
    nose.position.set(0.42, 0, 0);
    droneMesh.add(nose);

    if (trajectory.length > 0) {
      const p0 = trajectory[0].position || [5, 5, 5];
      droneMesh.position.set(p0[0], p0[1], p0[2]);
    }
    scene.add(droneMesh);
  }

  function buildLidar() {
    const positions = new Float32Array(NUM_RAYS * 2 * 3);
    const colors = new Float32Array(NUM_RAYS * 2 * 3);
    const geom = new THREE.BufferGeometry();
    geom.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geom.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    lidarSegments = new THREE.LineSegments(
      geom,
      new THREE.LineBasicMaterial({ vertexColors: true, transparent: true, opacity: 0.65 })
    );
    scene.add(lidarSegments);
  }

  function buildTrajectoryLine() {
    const maxPoints = Math.max(numSteps + 50, 1000);
    const positions = new Float32Array(maxPoints * 3);
    const geom = new THREE.BufferGeometry();
    geom.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geom.setDrawRange(0, 0);

    const mat = new THREE.LineBasicMaterial({
      color: 0x00f2fe,
      transparent: true,
      opacity: 0.85,
      linewidth: 2
    });
    trajectoryLine = new THREE.Line(geom, mat);
    scene.add(trajectoryLine);
  }

  function applyState(alphaStep) {
    if (trajectory.length === 0) return;
    const i0 = Math.floor(alphaStep);
    const i1 = Math.min(i0 + 1, numSteps);
    const frac = alphaStep - i0;

    const s0 = trajectory[i0];
    const s1 = trajectory[i1];

    // 1. Position Vector Interpolation
    const p0 = s0.position;
    const p1 = s1.position;
    const x = p0[0] + frac * (p1[0] - p0[0]);
    const y = p0[1] + frac * (p1[1] - p0[1]);
    const z = p0[2] + frac * (p1[2] - p0[2]);

    droneMesh.position.set(x, y, z);

    // 2. Attitude Quaternion Slerp (6-DOF) or Heading (3-DOF)
    if (is6DOF && s0.quaternion && s1.quaternion) {
      const q0 = new THREE.Quaternion(s0.quaternion[1], s0.quaternion[2], s0.quaternion[3], s0.quaternion[0]);
      const q1 = new THREE.Quaternion(s1.quaternion[1], s1.quaternion[2], s1.quaternion[3], s1.quaternion[0]);
      droneMesh.quaternion.copy(q0).slerp(q1, frac);
    } else {
      const v0 = s0.velocity || [0, 0, 0];
      const v1 = s1.velocity || [0, 0, 0];
      const vx = v0[0] + frac * (v1[0] - v0[0]);
      const vy = v0[1] + frac * (v1[1] - v0[1]);
      const vz = v0[2] + frac * (v1[2] - v0[2]);
      const yaw = Math.atan2(vy, vx);
      const pitch = -Math.atan2(vz, Math.sqrt(vx * vx + vy * vy)) * 0.5;
      droneMesh.rotation.set(0, pitch, yaw, 'ZYX');
    }

    // 3. Progressive Trajectory Trail
    const posArr = trajectoryLine.geometry.attributes.position.array;
    let ptr = 0;
    for (let i = 0; i <= i0; i++) {
      const p = trajectory[i].position;
      posArr[ptr++] = p[0];
      posArr[ptr++] = p[1];
      posArr[ptr++] = p[2];
    }
    posArr[ptr++] = x;
    posArr[ptr++] = y;
    posArr[ptr++] = z;
    trajectoryLine.geometry.setDrawRange(0, i0 + 2);
    trajectoryLine.geometry.attributes.position.needsUpdate = true;

    // 4. LiDAR Rays
    if (lidarSegments) {
      const lPos = lidarSegments.geometry.attributes.position.array;
      const lCol = lidarSegments.geometry.attributes.color.array;
      const ranges = s0.lidar || [];
      for (let i = 0; i < NUM_RAYS; i++) {
        const ray = LIDAR_RAYS[i];
        const dist = (ranges[i] !== undefined) ? ranges[i] : 10.0;
        const idx = i * 6;
        lPos[idx] = x; lPos[idx + 1] = y; lPos[idx + 2] = z;
        lPos[idx + 3] = x + ray.x * dist;
        lPos[idx + 4] = y + ray.y * dist;
        lPos[idx + 5] = z + ray.z * dist;

        let r = 0.0, g = 0.95, b = 1.0;
        if (dist < 3.0) { r = 1.0; g = 0.2; b = 0.2; }
        else if (dist < 7.0) { r = 0.95; g = 0.7; b = 0.1; }
        lCol[idx] = r; lCol[idx + 1] = g; lCol[idx + 2] = b;
        lCol[idx + 3] = r; lCol[idx + 4] = g; lCol[idx + 5] = b;
      }
      lidarSegments.geometry.attributes.position.needsUpdate = true;
      lidarSegments.geometry.attributes.color.needsUpdate = true;
    }

    // 5. Update Camera in Follow Mode
    if (cameraFollow) {
      const forward = new THREE.Vector3(1, 0, 0).applyQuaternion(droneMesh.quaternion).normalize();
      const targetCam = new THREE.Vector3(x, y, z).subScaledVector(forward, 6.0);
      targetCam.z += 2.5;
      camera.position.lerp(targetCam, 0.08);
      camera.lookAt(x, y, z + 0.5);
    }

    // 6. Update HUD
    const speed = s0.speed + frac * (s1.speed - s0.speed);
    const distGoal = s0.distance_to_goal + frac * (s1.distance_to_goal - s0.distance_to_goal);
    const cumRew = s0.cumulative_reward + frac * (s1.cumulative_reward - s0.cumulative_reward);

    const stepEl = document.getElementById('hud-step');
    const posEl = document.getElementById('hud-pos');
    const velEl = document.getElementById('hud-vel');
    const distEl = document.getElementById('hud-dist');
    const rewEl = document.getElementById('hud-reward');
    const scrubEl = document.getElementById('sim-scrubber');

    if (stepEl) stepEl.textContent = `Step ${i0} / ${numSteps}`;
    if (posEl) posEl.textContent = `(${x.toFixed(1)}, ${y.toFixed(1)}, ${z.toFixed(1)})`;
    if (velEl) velEl.textContent = `${speed.toFixed(1)} m/s`;
    if (distEl) distEl.textContent = `${distGoal.toFixed(1)} m`;
    if (rewEl) rewEl.textContent = cumRew.toFixed(1);
    if (scrubEl && document.activeElement !== scrubEl) scrubEl.value = Math.round(alphaStep);
  }

  function bindControls() {
    const startBtn = document.getElementById('btn-sim-start');
    const pauseBtn = document.getElementById('btn-sim-pause');
    const resetBtn = document.getElementById('btn-sim-reset');
    const scrub = document.getElementById('sim-scrubber');

    if (scrub) {
      scrub.disabled = false;
      scrub.max = numSteps;
      scrub.value = 0;
      scrub.addEventListener('input', (e) => {
        playhead = parseFloat(e.target.value);
        applyState(playhead);
      });
    }

    if (startBtn) {
      startBtn.addEventListener('click', () => {
        if (playhead >= numSteps) {
          playhead = 0.0;
        }
        isRunning = true;
        const statusText = document.getElementById('sim-status-text');
        if (statusText) statusText.textContent = 'PLAYING';
        startBtn.textContent = 'RESUME';
      });
    }

    if (pauseBtn) {
      pauseBtn.addEventListener('click', () => {
        isRunning = false;
        const statusText = document.getElementById('sim-status-text');
        if (statusText) statusText.textContent = 'PAUSED';
      });
    }

    if (resetBtn) {
      resetBtn.addEventListener('click', () => {
        isRunning = false;
        playhead = 0.0;
        applyState(0.0);
        const statusText = document.getElementById('sim-status-text');
        if (statusText) statusText.textContent = 'READY';
        if (startBtn) startBtn.textContent = 'START';
      });
    }

    // Mouse drag for Free Orbit Camera
    renderer.domElement.addEventListener('mousedown', (e) => {
      isDragging = true;
      cameraFollow = false;
      prevMousePos = { x: e.clientX, y: e.clientY };
    });

    window.addEventListener('mouseup', () => { isDragging = false; });

    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      const deltaX = e.clientX - prevMousePos.x;
      const deltaY = e.clientY - prevMousePos.y;
      prevMousePos = { x: e.clientX, y: e.clientY };

      spherical.theta -= deltaX * 0.008;
      spherical.phi = Math.max(0.2, Math.min(Math.PI / 2 - 0.05, spherical.phi - deltaY * 0.008));
      updateCameraPosition();
    });

    window.addEventListener('resize', () => {
      if (!container) return;
      const w = container.clientWidth;
      const h = container.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    });
  }

  function updateCameraPosition() {
    const cx = ARENA_X / 2 + spherical.radius * Math.sin(spherical.phi) * Math.cos(spherical.theta);
    const cy = ARENA_Y / 2 + spherical.radius * Math.sin(spherical.phi) * Math.sin(spherical.theta);
    const cz = ARENA_Z / 2 + spherical.radius * Math.cos(spherical.phi);
    camera.position.set(cx, cy, cz);
    camera.lookAt(new THREE.Vector3(ARENA_X / 2, ARENA_Y / 2, ARENA_Z / 2));
  }

  // Animation Loop
  let lastTime = performance.now();

  function render(time) {
    requestAnimationFrame(render);

    const deltaMs = Math.min(time - lastTime, 100);
    lastTime = time;

    // Advance simulation playhead
    if (isRunning && trajectory.length > 0) {
      const deltaSimSec = (deltaMs / 1000.0) * playbackSpeed;
      const deltaStep = deltaSimSec / dt;
      playhead += deltaStep;

      if (playhead >= numSteps) {
        playhead = numSteps;
        isRunning = false;
        const statusText = document.getElementById('sim-status-text');
        if (statusText) statusText.textContent = flightData.outcome || 'COMPLETED';
      }
      applyState(playhead);

      // Spin propellers
      propMeshes.forEach((p, idx) => {
        p.rotation.z += (idx % 2 === 0 ? 0.45 : -0.45) * playbackSpeed;
      });
    }

    // Pulsing target beacon animation
    if (targetMesh) {
      targetMesh.rotation.y += 0.02;
      targetMesh.rotation.x += 0.01;
      const scale = 1.0 + Math.sin(time * 0.005) * 0.15;
      targetMesh.scale.set(scale, scale, scale);
    }

    renderer.render(scene, camera);
  }

  // Self-initialize when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
